) AS (
  VALUES 
    (134::BIGINT, 'El profe da el curso compartido con otra profe, pero lo que da él lo hace muy sencillo. Deja algunos trabajos durante clase y dos ensayos evaluados. Solo da como una hora de las cuatro de clase. No da mucha explicación de los temas del curso, pero tampoco es muy exigente con los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-10-02T00:00:00+00:00'::TIMESTAMPTZ, '5c481d8262f1c667e56a848f056ea7a820cdb9eaf2dd5a00852e2f0ede6babf7'::TEXT, ARRAY[1357]::BIGINT[]),
    (134::BIGINT, 'La perrita de Carolina, (el curso lo dan los dos juntos), legalmente el mae le tienen miedo a la señora esa intensa jajaja, la parte del curso que se lleva con el super fácil, la clase dura como 20 min y deja dos trabajos bien tontos'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '0b64ddc276e2c6c3dfb2e9e14e089e9194e06ea016823571478756394b3aea3d'::TEXT, ARRAY[1357]::BIGINT[]),
    (134::BIGINT, 'Las clases duran 20 minutos, todo se trabaja en grupos. El no hace mucho, pero tampoco pide mucho. Sospecho que nunca abrió las entregas.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, '14d26f0978b4d1e08ad7f6eb3a5852b17e12277fc56c6784622a04915517d6e5'::TEXT, ARRAY[628]::BIGINT[]),
    (134::BIGINT, 'Un súper profe para nada pesado. Yo lo llevé virtual y fue el curso más ligero de todo el semestre. Totalmente volvería a llevar un curso con él.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '27830e05e896f2f3ea45fc1c1c8c7d34590d1cbc2d75d7807d3266a6659abb52'::TEXT, ARRAY[628]::BIGINT[]),
    (134::BIGINT, 'Los seminarios y cursos de este tipo ya de todos modos son una pega. Pero llevarlo con este profe hace que sea super fácil. Las clases son muy cortas y los trabajos muy fáciles. Si tienen buen grupo de trabajo el curso ni se siente. Ni lo duden si tienen la oportunidad de matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-09-07T00:00:00+00:00'::TIMESTAMPTZ, '721db34870295c3f1c8138a595ca57c73bbadee60d244756880eac5ef5877037'::TEXT, ARRAY[628]::BIGINT[]),
    (134::BIGINT, 'Un profe muy chill. Sus clases tratan de completar los trabajos asignados (son cortos no se duran mucho). A pesar de que no pase lista de asistencia, es importante ir porque los trabajos se entregan durante la clase. No se aprende mucho, pero entrega notas a tiempo.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2024-11-14T00:00:00+00:00'::TIMESTAMPTZ, '8ab9b3fad4d01d6062997c9d4a37a19f3dc7ca781793fed163910755d74d3866'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'Intenta hacer las clases un poco más dinámicas de lo que sería un seminario. Muchas veces manda a ver documentales en vez de tener sesiones sincrónicas. En general los trabajos más importantes son de realizar ensayos sobre una lectura o los documentales. Califica hasta el puro final.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'fd0d533e33790af54530fa114fa61c660d185e968b0f9ad85febd33edb9820f0'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'La mitad del curso con el profe se basa en hacer 2 ensayos en grupo. Las clase es un poco aburrida pero si pone atencion casi que no hace falta hacer las lecturas que deja semanalmente. Es buena gente y califica suave'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-11-19T00:00:00+00:00'::TIMESTAMPTZ, '348485c6dad999286a20ba1e036ab8cc14810fedc2ac77a518ce79f861a030c8'::TEXT, ARRAY[1357]::BIGINT[]),
    (134::BIGINT, 'Es un profe joven, las clases son similares a sociales del cole. Manda a ver documentales sumamente interesante que ayudan a entender el dinamismo del gobierno actualmente y de algunos detalles que por nuestra edad no sabemos que existieron sucesos de un gran cambio social.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6b2c758595e1b51f61374ae84824fd9ab35c78e5fe440ee7c269d14ff53fc28f'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'Demasiado fácil con este profe, delen sin miedo'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'e887fc5e9e99e786cc41e3d00f9998945c075d65b1cfbb0f7157424b2c85efbf'::TEXT, ARRAY[628]::BIGINT[]),
    (134::BIGINT, 'De los cursos más desorganizados que he visto. Faltó las primeras 6 semanas de clase, o sea, hasta semana 6 tuvimos nuestra primera clase normal. Luego, no comunica los trabajos que deja, no sube las presentaciones, no es para nada claro en lo que hay que entregar.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '2ceb0be6a89c39d2aab8413cb8868bec1fdc542bca6e6b2def66c3c5563abd78'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'El semestre del TEC dura 16 semanas y dejó el 80% de las evaluaciones del curso faltando 3 semanas. Esto habiendo faltado 4 semanas, sin dar explicaciòn alguna. La materia que da es demasiado fácil y todo se puede saber por lógica. Parece que no quiere dar el curso'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, '1e5d191b7ba08322c473d2b6c85c0b77ad5478e0934c760fd7bf3771f5b5684f'::TEXT, ARRAY[628]::BIGINT[]),
    (134::BIGINT, 'El semestre del TEC dura 15 semanas y dejó el 80% de las evaluaciones del curso faltando 3 semanas. Esto habiendo faltado a 4 semanas. La materia que da es demasiado fácil y todo se puede saber por lógica. Y se nota demasiado que es socialista xd'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2022-05-29T00:00:00+00:00'::TIMESTAMPTZ, '94aa2f2268949e7eb727858e0b13b2bf34af0680e50e8ecd326d945187e0322b'::TEXT, ARRAY[628]::BIGINT[]),
    (134::BIGINT, 'El curso fue bastante confuso, honestamente nunca pude entender con claridad la idea de este, el ambiente con el profesor es ameno y las clases muy cortas. Eso si, las evaluaciones tienen mucho peso hay que prestarles atencion para la nota.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'd1bccfc397c808215205afd6f66ff230e967bcce20236169468202652ec0ae73'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'La evaluación son básicamente 2 exámenes (ensayos), 3 análisis de películas y un proyecto, siendo los dos últimos grupales. El profe es buena nota y el curso es muy fácil solo que a veces si es un toque aburrido, pero en general se aprende.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'e927d64ed0cb8a391b03faaee81c384cdbc614b4715d6f64370bbf5525fb03ca'::TEXT, ARRAY[628]::BIGINT[]),
    (134::BIGINT, 'La verdad, pésimo profesor. Uno de los peores cursos y clases muy muy muy aburridas. El curso es bastante fácil pero no se aprende nada. Al final se pasa en presentaciones de PP y presentaciones de estudiantes. Pero al menos no hace el curso complicado'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '03747e05b1948e6d049278931780008eb8ab39ff5714eae56d958ebf1e04b1be'::TEXT, ARRAY[1004, 3230]::BIGINT[]),
    (134::BIGINT, 'El curso es pasable, en este semstre dejo unas lecturas con las que sediscutía despupés en clase, pidió 2 ensayos basados en los que se había visto y si uno los fundamenta bien el curso sale fácil. Me pareció interesante pero el profe no es muy energético por lo que puede ser aburrido para otros.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, '755079033ea5940f90c34ef8c16217af74c36a3aa75aad2fd36578c34bf918e3'::TEXT, ARRAY[1357]::BIGINT[]),
    (134::BIGINT, 'El profe es un poco aburrido, pero no hace el curso difícil. Los exámenes que él deja son 0% a lo que estamos acostumbrados los ingenieros, nos puso a hacer ensayos con citas y pos, que bostezo jaja. Muy interesante la meteria pero el profe se desaparece después de la clase'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '7253a4be6b0fb35bc81903cbfb2e46c68310d36ee8bccfa4dcec29b89eefc14d'::TEXT, ARRAY[1357]::BIGINT[]),
    (134::BIGINT, 'Las clases virtuales son aburridillas, se pierde toda la gracia de estos cursos, lamentablemente. Es un buen profesor, una persona agradable y si puede llevar con él presencial, mejor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '4ccf921b44f1f2c869e9158c3c434722cd3b5e689248dada3d0b94f83f959389'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'Antes de la pandemia el profe manejaba bien la clase (su enfoque era la identidad). Con la pandemia desapareció, no contestaba correos y dejó varios trabajos para el final. Es super accesible con las entregas pero el enfoque que le da al curso no es muy llamativo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'bd87301f81f397eea65981a968d71c2453b315d9404c5efba4b8006e1c92e5c5'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'Las clases presenciales eran algo interesantes, cuando pasaron a ser virtuales se desapareció un tiempo y no contestaba correos. Tratar de comunicarse con él es muy difícil, nunca contesta, Es muy fácil el curso.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'd967dff351be7adbc865ccb6b2be2ddfacb1a19edac87eb212b7dab8f44f78c1'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'Antes de la pandemia las clases eran relativamente interesantes. Durante la pandemia las clases fueron asincrónicas con presentaciones de powerpoint con audios y era un bostezo. Muchas de las tareas eran ver videos de 1+ horas. La comunicación fue malísima (no contesta correos). Fácil pasar eso sí'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '6937aee307a77dc9caa1e53ccd498dbfe051472b715aa99dcc251cdda46f8068'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'Muy fácil, 100% recomendado, el profe es muy tuanis'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'faefedb191525106c6b6d6ef1f1c3be7540d20c2999e6cbbb5da8467cef52c1a'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'Es muy fácil, solo que las clases son muy aburridas. Es ver a los compañeros exponer. Sin embargo, repito, se pasa muy fácil el curso, y no es de asistencia obligatoria. Sí recomiendo al profe.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '639ae880e62dcd2ad3f03422905b9f719b41ec5fdd5f0a6a18403ad7e4fec836'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'Las clases consisten en ver a gente exponer, entonces es bastante aburrido. Usted tiene que exponer una vez pero es muy fácil, y hacer trabajos escritos a lo largo del semestre algo tediosos, pero se pasa fácil.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '2e7f5140002d363c913b0abc972da6a454a864f86921756aced29bb890cdd1d2'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'El curso se pasa fácil, solamente que califica un poco rudo. Hay que ponerle pero es muy buen profe'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'e53db7968c14f88044f9e39688492f829bbbe77474e80829e1d79b78cfe42235'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'Un curso fácil, interesante, pero definitivamente menos importante que otros. El profesor es relajado, las clases son básicamente exposiciones en grupos de 4 de alguna de las lecturas del curso, ver 3 películas y comentarlas, y discusiones grupales de algún tema social y tecnología. -J'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2018-08-04T00:00:00+00:00'::TIMESTAMPTZ, '35c0b4006b2646d12c78d7d0dc8a645f5954cb7010bef14871b499e4ba20e2ac'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'En general un buen profesor. No tengo ninguna queja. Un curso muy pasable.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2018-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'd160e97a6a6a165ee35dc8ad1ef1f10e91bc55f7469a9c94b2d2185651627d28'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'Facil Facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '175b9f38947162c72b98299df82ec3c087dda6c254c66e05f8fa31ebd1295b85'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'Demasiadas tareas y lecturas. Hace la clase entretenida'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'd63c63e4ed048fdb6d4a362a884d89780c10d26e5e0be1dcb78a08f1462fb52f'::TEXT, ARRAY[1004, 3230]::BIGINT[]),
    (134::BIGINT, 'Buen profe. Muchas tareas, demasiadas lecturas. Pero se pasa bien el curso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '38f263a95bb3a0f78c860065e4945e80509e580959cb074df94cb92f8a914225'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'a635ba869252cd0e8d200f90fd859b0cda6e4ac8b133396292963a0b83c3cd5e'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'Todas las semanas hay que leer lecturas no muy entendibles pero usualmente cortas, y además entregar resúmenes de estas. Se hace también una exposición e investigación y con eso se pasa el curso. El curso es sencillo y el profe pura vida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'fc040db3476ee2b207b7b984d877cf3dd63d424806a9d49855ac2b255c2323df'::TEXT, ARRAY[1004]::BIGINT[]),
    (134::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a6f4a94552cd0ae8d40d060b4f0a30a40155ae3b51ca7a73f0f876b1702ed72b'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'Muy dedicado y se sienta en los zapatos de lo estudiantes osea trata ser uno de nosotros, lo aprecio mucho y se ve que sabe bastante de la materia'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd0534e1c01b20ea8daee58e6bf70334db42a519a44bff45aea820d4c4694dabf'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'Es de los pocos profes que hacen examenes durante la clase en esta materia, los cuales son un poco dificiles. En si la clases consisten en exponer una vez y ver a otros exponer el resto del semestre'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'c639d0cb509ced69269b2098b60641c1455a597ed97d363a45377acff7e30856'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'Pura vida, las clases son tranquilas, trabajos que dan pistas para el examen, los examenes no son rudos(si repasó aunque sea antes las diapositivas o puso atencion en clase), un buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2016-06-12T00:00:00+00:00'::TIMESTAMPTZ, '94cf9a0a6eee2b176490209eeecec2e0171074018005fda355ea0bbe1e03eb72'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'Bueno! Relax'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'e32b3c6138da0981b8c3abbbe503dc895396690e35744b8b5c60a9fd0aa0e4db'::TEXT, ARRAY[559]::BIGINT[]),
    (134::BIGINT, 'La clase es aburrida asi como el profe, aveces si saca uno que otro chiste. Es facil, practicamente las clases con el es ir exponer, comentar e irse, no le quita mucho tiempo. Los examanes si son un poco complicados.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2016-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'ef69f6b7d5918cd4011ab5d227df8637b011e756ca5e7bfa6232d349b4489d63'::TEXT, ARRAY[559]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
